VALUES (22787, 'tt0365929', NULL, 'Whiteout', 'Whiteout', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/kkXXA3353MX60B8PRSkTGRabxXu.jpg', 'https://image.tmdb.org/t/p/original/18uabdgGRxX4bJr3i6Zon7EXGlA.jpg', 'The only U.S. Marshal assigned to Antarctica, Carrie Stetko will soon leave the harsh environment behind for good – in three days, the sun will set and the Amundsen-Scott Research Station will shut down for the long winter. When a body is discovered out on the open ice, Carrie''s investigation into the continent''s first homicide plunges her deep into a mystery that may cost her her own life.', NULL, NULL, 2.0376, 5.603, 0, 1.04, '2026-11-20 00:55:15', '2026-11-20 00:55:15')
