VALUES (55655, 'tt1439573', NULL, 'The Sound of Insects: Record of a Mummy', 'Das Summen der Insekten', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/jEzbSeVlQU5KmMTSCj0PwUkaSKJ.jpg', 'https://image.tmdb.org/t/p/original/bupxbobHUMndrnsSWLSHqPFvwD4.jpg', 'The incredible story of how the mummified corpse of a 40-year-old man was discovered by a hunter in one of the most remote parts of the country. The dead man''s detailed notes reveal that he actually committed suicide through self-imposed starvation only the summer before. Liechti''s film is a stunning rapprochement of a fictional text, which itself is based upon a true event: a cinematic manifesto for life, challenged by the main character''s radical renunciation of life itself.', NULL, NULL, 0.4241, 6.8, 0, 8.01, '2026-11-20 00:55:15', '2026-11-20 00:55:15')
