VALUES (6479, 'tt0480249', NULL, 'I Am Legend', 'I Am Legend', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/fhbiz5BsGUVEZmzPP72SoPlbMz0.jpg', 'https://image.tmdb.org/t/p/original/ePgD1cwmklyrFBjl6z96IuixuSY.jpg', 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', NULL, NULL, 12.0142, 7.226, 0, 2.97185185185185183e+01, '2026-07-15 12:01:52', '2026-11-20 00:55:15')
