VALUES (1584, 'tt0332379', NULL, 'The School of Rock', 'The School of Rock', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/zXLXaepIBvFVLU25DH3wv4IPSbe.jpg', 'https://image.tmdb.org/t/p/original/k5MTAtE9CCi5TWA84qaFMYv3ajB.jpg', 'Fired from his band and hard up for cash, guitarist and vocalist Dewey Finn finagles his way into a job as a fifth-grade substitute teacher at a private school, where he secretly begins teaching his straight-A students the finer points of rock ''n'' roll and the power of sticking it to the man. But as the school’s stern principal closes in and the Battle of the Bands looms, Dewey must risk everything to prove that rock ''n'' roll can change lives.', NULL, NULL, 8.4002, 7.093, 0, 1.21833333333333335e+01, '2026-07-15 12:01:52', '2026-11-20 00:55:15')
