VALUES (122906, 'tt2194499', NULL, 'About Time', 'About Time', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/ls6zswrOZVhCXQBh96DlbnLBajM.jpg', 'https://image.tmdb.org/t/p/original/einbto9qLXFx9QXxEHylaxDbKPx.jpg', 'The night after another unsatisfactory New Year''s party, Tim''s father reveals to him that the men in their family have the ability to travel through time. They can''t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.', NULL, NULL, 13.826, 7.9, 0, 4.03613888888888894e+01, '2026-07-15 12:01:52', '2026-11-20 00:55:15')
