VALUES (212778, 'tt2883512', NULL, 'Chef', 'Chef', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/hyp8EXDmO4dSC8V6Q5jU7gD1kcg.jpg', 'https://image.tmdb.org/t/p/original/igVNCpS132rOqrnDsrVYW5HCIsM.jpg', 'When Chef Carl Casper suddenly quits his job at a prominent Los Angeles restaurant after refusing to compromise his creative integrity for its controlling owner, he is left to figure out what''s next. Finding himself in Miami, he teams up with his ex-wife, his friend and his son to launch a food truck. Taking to the road, Chef Carl goes back to his roots to reignite his passion for the kitchen -- and zest for life and love.', NULL, NULL, 6.1753, 7.115, 0, 1.81242857142857154e+01, '2026-07-20 01:02:04', '2026-11-20 00:55:15')
