VALUES (134374, 'tt1980209', NULL, 'Pain & Gain', 'Pain & Gain', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/9WqA0Ry9wmTzFvom8mNbcyKZQgP.jpg', 'https://image.tmdb.org/t/p/original/73Ridh5DhGBmKAiwq8gy3IbtthT.jpg', 'Daniel Lugo, manager of the Sun Gym in 1990s Miami, decides that there is only one way to achieve his version of the American dream: extortion. To achieve his goal, he recruits musclemen Paul and Adrian as accomplices. After several failed attempts, they abduct rich businessman Victor Kershaw and convince him to sign over all his assets to them. But when Kershaw makes it out alive, authorities are reluctant to believe his story.', NULL, NULL, 4.9398, 6.299, 0, 1.87085714285714281e+01, '2026-07-20 04:02:06', '2026-11-20 00:55:15')
