VALUES (800497, 'tt9288692', NULL, 'Werewolves Within', 'Werewolves Within', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/5CGgbgyvmE39Yoqa80GKsgClbQm.jpg', 'https://image.tmdb.org/t/p/original/ae25gpphxDPEYGUxvAGmR07oQqC.jpg', 'When a proposed pipeline creates hostilities between residents of a small town, a newly-arrived forest ranger must keep the peace after a snowstorm confines the townspeople to an old lodge. But when a mysterious creature begins terrorizing the group, their worst tendencies and prejudices rise to the surface, and it is up to the ranger to keep the residents alive, both from each other and the monster which plagues them.', NULL, NULL, 4.493, 6.0, 0, 8.30999999999999872e+00, '2026-07-29 20:51:09', '2026-11-20 00:55:15')
