VALUES (287903, 'tt3850590', NULL, 'Krampus', 'Krampus', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/sAolMRD9rFSTU7tssfFuLEJJa7w.jpg', 'https://image.tmdb.org/t/p/original/h3X1YZXNeklLNKRVOS6DHGRosog.jpg', 'When his dysfunctional family clashes over the holidays, young Max is disillusioned and turns his back on Christmas.  Little does he know, this lack of festive spirit has unleashed the wrath of Krampus: a demonic force of ancient evil intent on punishing non-believers.', NULL, NULL, 7.393, 6.208, 0, 20.094375, '2026-07-30 18:28:39', '2026-11-20 00:55:15')
