VALUES (11046, 'tt0065207', NULL, 'Where Eagles Dare', 'Where Eagles Dare', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/dnyiVS4Ad4w4rfS4Bm1YalEdonx.jpg', 'https://image.tmdb.org/t/p/original/vzavBt9c6v4zBaGiwQDO21aNQG9.jpg', 'World War II is raging, and an American general has been captured and is being held hostage in the Schloss Adler, a Bavarian castle that''s nearly impossible to breach. It''s up to a group of skilled Allied soldiers to liberate the general before it''s too late.', NULL, NULL, 4.1261, 7.521, 0, 14.2875, '2026-07-31 03:33:23', '2026-11-20 00:55:15')
